using AcxiomCRM.Web.Data; using AcxiomCRM.Web.Models; using AcxiomCRM.Web.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Web.Controllers;
[Authorize] public class OpportunitiesController:Controller{readonly ApplicationDbContext db;readonly UserManager<ApplicationUser> um;readonly AuditService audit;readonly RiskEngine risk;public OpportunitiesController(ApplicationDbContext d,UserManager<ApplicationUser> u,AuditService a,RiskEngine r){db=d;um=u;audit=a;risk=r;}string U=>um.GetUserId(User)!;bool Priv=>User.IsInRole("Admin")||User.IsInRole("Manager");
public async Task<IActionResult> Index(string? q){var x=db.Opportunities.Include(o=>o.Customer).Include(o=>o.Owner).AsQueryable();if(!Priv)x=x.Where(o=>o.OwnerId==U);if(!string.IsNullOrWhiteSpace(q))x=x.Where(o=>o.OpportunityName.Contains(q)||o.Customer!.CustomerName.Contains(q));return View(await x.OrderByDescending(o=>o.ModifiedAt).ToListAsync());}
public async Task<IActionResult>Create()=>View(new OpportunityVm());
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(OpportunityVm vm){if(vm.Status==OpportunityStatus.Open&&vm.Amount<=0)ModelState.AddModelError("Amount","Opportunity Amount must be greater than 0.");if(vm.Status==OpportunityStatus.Open&&vm.ExpectedCloseDate.Date<DateTime.UtcNow.Date)ModelState.AddModelError("ExpectedCloseDate","Expected Close Date cannot be in the past.");if(!ModelState.IsValid)return View(vm);var o=new Opportunity{OpportunityName=vm.OpportunityName,CustomerId=vm.CustomerId,LeadId=vm.LeadId,Amount=vm.Amount,Probability=vm.Probability,Stage=vm.Stage,Status=vm.Status,ExpectedCloseDate=vm.ExpectedCloseDate.Date,OwnerId=Priv&&vm.OwnerId!=null?vm.OwnerId:U,Notes=vm.Notes};db.Opportunities.Add(o);await db.SaveChangesAsync();await audit.LogAsync("CREATE","Opportunity",o.Id.ToString(),null,o.OpportunityName,U);return RedirectToAction(nameof(Index));}
public async Task<IActionResult>Edit(int id){var o=await db.Opportunities.FindAsync(id);if(o==null)return NotFound();if(!Priv&&o.OwnerId!=U)return Forbid();return View(new OpportunityVm{Id=o.Id,OpportunityName=o.OpportunityName,CustomerId=o.CustomerId,LeadId=o.LeadId,Amount=o.Amount,Probability=o.Probability,Stage=o.Stage,Status=o.Status,ExpectedCloseDate=o.ExpectedCloseDate,OwnerId=o.OwnerId,Notes=o.Notes});}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(int id,OpportunityVm vm){var o=await db.Opportunities.FindAsync(id);if(o==null)return NotFound();if(!Priv&&o.OwnerId!=U)return Forbid();if(vm.Status==OpportunityStatus.Open&&vm.Amount<=0)ModelState.AddModelError("Amount","Opportunity Amount must be greater than 0.");if(vm.Status==OpportunityStatus.Open&&vm.ExpectedCloseDate.Date<DateTime.UtcNow.Date)ModelState.AddModelError("ExpectedCloseDate","Expected Close Date cannot be in the past.");if(!ModelState.IsValid)return View(vm);var old=$"{o.Stage}|{o.Amount}|{o.Probability}|{o.Status}";o.OpportunityName=vm.OpportunityName;o.CustomerId=vm.CustomerId;o.LeadId=vm.LeadId;o.Amount=vm.Amount;o.Probability=vm.Probability;o.Stage=vm.Stage;o.Status=vm.Status;o.ExpectedCloseDate=vm.ExpectedCloseDate.Date;o.Notes=vm.Notes;o.ModifiedAt=DateTime.UtcNow;if(Priv&&vm.OwnerId!=null)o.OwnerId=vm.OwnerId;await db.SaveChangesAsync();await audit.LogAsync("UPDATE","Opportunity",id.ToString(),old,$"{o.Stage}|{o.Amount}|{o.Probability}|{o.Status}",U);return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Analyze(int id){var o=await db.Opportunities.FindAsync(id);if(o==null)return NotFound();if(!Priv&&o.OwnerId!=U)return Forbid();var result=await risk.AnalyzeAsync(id);ViewBag.Opportunity=o;return View("Risk",result);}
}
